#!/usr/bin/env node
// scripts/vendor-codex-schema.js
//
// Vendor or drift-check the Codex App Server protocol schema generated by an
// installed Codex CLI.

import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { compareCodexSchema, CODEX_SCHEMA_FILENAME } from "../hub/providers/codex-schema/index.js";

const REPO_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const DEFAULT_OUT_ROOT = join(REPO_ROOT, "hub", "providers", "codex-schema");
const GENERATED_SCHEMA_FILES = Object.freeze({
  outgoingCall: "ClientRequest.json",
  incomingEvent: "ServerNotification.json",
  serverRequest: "ServerRequest.json",
  response: "JSONRPCResponse.json",
  message: "JSONRPCMessage.json",
});

export function parseArgs(argv = process.argv.slice(2)) {
  const opts = {
    check: false,
    command: "codex",
    outRoot: DEFAULT_OUT_ROOT,
    channel: "stable",
  };
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--check") opts.check = true;
    else if (arg === "--command") opts.command = nextArg(argv, ++i, arg);
    else if (arg === "--out-root") opts.outRoot = resolve(nextArg(argv, ++i, arg));
    else if (arg === "--channel") opts.channel = nextArg(argv, ++i, arg);
    else if (arg === "--help" || arg === "-h") opts.help = true;
    else throw new Error(`Unknown argument: ${arg}`);
  }
  return opts;
}

export function main(argv = process.argv.slice(2), io = console) {
  const opts = parseArgs(argv);
  if (opts.help) {
    io.log("Usage: node scripts/vendor-codex-schema.js [--check] [--command codex] [--out-root PATH] [--channel stable]");
    return 0;
  }
  const generated = generateSchema(opts.command, { channel: opts.channel });
  if (!generated.ok) {
    writeError(io, `error: unable to generate Codex schema: ${generated.reason}`);
    return 1;
  }
  const versionDir = join(opts.outRoot, normalizeVersion(generated.version), normalizeSegment(opts.channel));
  const schemaPath = join(versionDir, CODEX_SCHEMA_FILENAME);
  if (opts.check) {
    return checkSchema(schemaPath, generated.schema, io);
  }
  mkdirSync(versionDir, { recursive: true });
  writeFileSync(schemaPath, `${JSON.stringify(generated.schema, null, 2)}\n`);
  io.log(`Vendored Codex schema ${generated.version} at ${schemaPath}`);
  return 0;
}

export function generateSchema(command = "codex", { channel = "stable" } = {}) {
  const versionResult = spawnSync(command, ["--version"], { encoding: "utf8" });
  if (versionResult.error) return { ok: false, reason: versionResult.error.message };
  const version = parseVersion(`${versionResult.stdout || ""}\n${versionResult.stderr || ""}`);
  const generatedRoot = mkdtempSync(join(tmpdir(), "codex-app-server-schema-"));
  try {
    const schemaResult = spawnSync(command, ["app-server", "generate-json-schema", "--out", generatedRoot], {
      encoding: "utf8",
      maxBuffer: 10 * 1024 * 1024,
    });
    if (schemaResult.error) return { ok: false, reason: schemaResult.error.message };
    if (schemaResult.status !== 0) {
      return {
        ok: false,
        reason: `codex app-server generate-json-schema exited ${schemaResult.status}: ${trim(schemaResult.stderr)}`,
      };
    }
    const normalizedVersion = normalizeVersion(version || "0.0.0");
    const schema = composeVendoredSchema({
      version: normalizedVersion,
      channel,
      generatedRoot,
    });
    return { ok: true, version: normalizedVersion, schema };
  } catch (err) {
    return { ok: false, reason: err.message };
  } finally {
    rmSync(generatedRoot, { recursive: true, force: true });
  }
}

function checkSchema(schemaPath, generatedSchema, io) {
  let vendored;
  try {
    vendored = JSON.parse(readFileSync(schemaPath, "utf8"));
  } catch (err) {
    writeError(io, `error: unable to read vendored schema at ${schemaPath}: ${err.message}`);
    return 1;
  }
  const comparison = compareCodexSchema(vendored, generatedSchema);
  if (!comparison.equal) {
    writeError(io, `error: Codex schema drift detected (${comparison.leftHash} != ${comparison.rightHash})`);
    return 1;
  }
  io.log(`Codex schema check passed at ${schemaPath}`);
  return 0;
}

function composeVendoredSchema({ version, channel, generatedRoot }) {
  const outgoingCall = readGeneratedSchema(generatedRoot, GENERATED_SCHEMA_FILES.outgoingCall);
  const incomingEvent = readGeneratedSchema(generatedRoot, GENERATED_SCHEMA_FILES.incomingEvent);
  const serverRequest = readGeneratedSchema(generatedRoot, GENERATED_SCHEMA_FILES.serverRequest);
  const response = readGeneratedSchema(generatedRoot, GENERATED_SCHEMA_FILES.response);
  const message = readGeneratedSchema(generatedRoot, GENERATED_SCHEMA_FILES.message);
  const normalizedVersion = normalizeVersion(version);
  const normalizedChannel = normalizeSegment(channel);
  const methods = extractMethodNames(outgoingCall);
  const events = extractMethodNames(incomingEvent);
  if (methods.length === 0) throw new Error("generated ClientRequest schema did not expose any methods");
  if (events.length === 0) throw new Error("generated ServerNotification schema did not expose any events");
  return {
    $id: `llm-tracker://codex-app-server/${normalizedVersion}/${normalizedChannel}/schema.json`,
    $schema: "http://json-schema.org/draft-07/schema#",
    metadata: {
      source: "codex app-server generate-json-schema",
      generatedBy: "scripts/vendor-codex-schema.js",
      codexVersion: normalizedVersion.slice(1),
      sourceFiles: Object.values(GENERATED_SCHEMA_FILES),
    },
    protocolVersion: normalizedVersion.slice(1),
    channel: normalizedChannel,
    transports: ["stdio", "unix", "websocket"],
    methods: methods.map((name) => ({ name })),
    events: events.map((name) => ({ name })),
    $defs: {
      OutgoingCall: outgoingCall,
      IncomingEvent: incomingEvent,
      ServerRequest: serverRequest,
      JsonRpcResponse: response,
      JsonRpcMessage: message,
    },
  };
}

function readGeneratedSchema(root, filename) {
  const file = join(root, filename);
  try {
    return JSON.parse(readFileSync(file, "utf8"));
  } catch (err) {
    throw new Error(`unable to read generated ${filename}: ${err.message}`);
  }
}

function extractMethodNames(schema) {
  const names = [];
  const seen = new Set();
  for (const variant of Array.isArray(schema?.oneOf) ? schema.oneOf : []) {
    for (const name of arrayOrEmpty(variant?.properties?.method?.enum)) {
      if (seen.has(name)) continue;
      seen.add(name);
      names.push(name);
    }
  }
  return names;
}

function parseVersion(text) {
  const match = String(text || "").match(/\b(?:codex\s+)?v?(\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?)\b/);
  return match ? match[1] : null;
}

function normalizeVersion(version) {
  const value = String(version || "").trim();
  if (!/^v?\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/.test(value)) {
    throw new Error(`Invalid Codex schema version: ${version}`);
  }
  return value.startsWith("v") ? value : `v${value}`;
}

function normalizeSegment(segment) {
  const value = String(segment || "").trim();
  if (!/^[a-z0-9][a-z0-9_.-]*$/.test(value)) throw new Error(`Invalid channel: ${segment}`);
  return value;
}

function arrayOrEmpty(value) {
  return Array.isArray(value) ? value.filter((item) => typeof item === "string" && item) : [];
}

function trim(value) {
  const text = String(value || "").trim();
  return text.length > 500 ? `${text.slice(0, 500)}...` : text;
}

function writeError(io, message) {
  if (typeof io.error === "function") io.error(message);
  else if (typeof io.warn === "function") io.warn(message);
  else io.log(message);
}

function nextArg(argv, index, flag) {
  if (!argv[index]) throw new Error(`${flag} requires a value`);
  return argv[index];
}

if (import.meta.url === `file://${process.argv[1]}`) {
  process.exitCode = main();
}
